/* Fine body selection: keep arms intact, edit with a small brush, and nudge the existing ellipse. */
(()=>{'use strict';const core=RayBodyRegion,$=id=>document.getElementById(id),manual=$('rayBodyManual'),wrap=$('canvasWrap');if(!manual)return;
 const originalRegions=bodyAiRegions;bodyAiRegions=function(pose,face,W,H){const regions=originalRegions(pose,face,W,H);Object.assign(regions,core.torso(pose,W,H));return regions;};
 RayBodyCore.setRegionMasker(core.mask);
 const apply=bodyApply;bodyApply=function(c,W,H,p){const selection=core.mask(p,W,H);if(!selection)return apply(c,W,H,p);const box=RayBodyPeople.bounds([p],W,H);if(!box)return apply(c,W,H,p);const before=c.getImageData(box.x,box.y,box.width,box.height);apply(c,W,H,p);const after=c.getImageData(box.x,box.y,box.width,box.height);core.blend(before.data,after.data,box,W,H,p);c.putImageData(after,box.x,box.y);};
 const block=document.createElement('section');block.className='body-region-tools';block.innerHTML='<h3>Sửa khung &amp; vùng eo</h3><p class="hint">Kéo khung vào eo, hoặc dùng bút Thu vùng tô phần cần giữ nguyên như cánh tay. Bút Nới vùng đưa phần đã loại vào lại. Chỉnh khung trước, sau đó bấm Thu / Nới để xem ảnh đổi.</p><div class="body-region-modes"><button type="button" data-region-mode="off">Kéo khung</button><button type="button" data-region-mode="erase">Bút thu vùng</button><button type="button" data-region-mode="paint">Bút nới vùng</button></div><label class="row"><span>Cỡ bút nhỏ <output></output></span><input type="range" min="0.003" max="0.15" step="0.001" value="0.025" aria-label="Cỡ bút sửa vùng cơ thể"></label><label class="body-arm-guard"><input type="checkbox" checked aria-label="Bảo vệ cánh tay khi chỉnh eo"> Giữ cánh tay khi chỉnh eo</label><div class="body-region-actions"><button type="button" data-region-action="frame-in">− Thu khung</button><button type="button" data-region-action="frame-out">＋ Nới khung</button><button type="button" data-region-action="left" aria-label="Dịch khung sang trái">←</button><button type="button" data-region-action="right" aria-label="Dịch khung sang phải">→</button><button type="button" data-region-action="up" aria-label="Dịch khung lên trên">↑</button><button type="button" data-region-action="down" aria-label="Dịch khung xuống dưới">↓</button></div><div class="body-region-amount"><label>Mỗi lần <input type="number" min="0.5" max="10" step="0.5" value="2" aria-label="Phần trăm thu nới mỗi lần"> %</label><button type="button" data-region-action="slim">− Thu vùng</button><button type="button" data-region-action="expand">＋ Nới vùng</button></div><button type="button" class="bbtn" data-region-action="clear">Xóa nét sửa vùng này</button><p class="hint" role="status"></p>';const advanced=document.createElement('details');advanced.className='ray-body-details ray-body-region-details';const summary=document.createElement('summary');summary.textContent='Sửa khung & bút vùng';advanced.append(summary,block);$('rayBodyPartHint').after(advanced);
 const overlay=document.createElement('canvas');overlay.id='bodyRegionBrush';overlay.setAttribute('aria-label','Tô sửa vùng chỉnh dáng trên ảnh');wrap.append(overlay);let mode='off';const brush=block.querySelector('input[type=range]'),status=block.querySelector('[role=status]');advanced.addEventListener('toggle',()=>{if(!advanced.open){mode='off';refresh();}});
 const part=()=>bodyPart(BODY.sel),editing=()=>!!source&&document.body.dataset.editorTool==='body'&&$('bodyBox').dataset.bodyMode==='manual'&&!document.querySelector('.film-workspace.is-result-preview');
 function refresh(){const p=part(),enabled=editing()&&!!p;overlay.hidden=!enabled||mode==='off';for(const b of block.querySelectorAll('button,input'))b.disabled=!source||BODY_AI.busy;for(const b of block.querySelectorAll('[data-region-mode]'))b.setAttribute('aria-pressed',String(b.dataset.regionMode===mode));brush.previousElementSibling.querySelector('output').textContent=(Number(brush.value)*100).toFixed(1)+'%';block.querySelector('input[type=checkbox]').checked=p?.regionProtectArms!==false;status.textContent=p?'Đang chỉnh '+p.name.toLowerCase()+'. '+(p.regionStrokes?.length||0)+' nét sửa vùng. Các thao tác đều có thể Hoàn tác.':'Chọn một bộ phận để sửa vùng.';paint();}
 function change(label,fn){const p=part();if(!source||!p||BODY_AI.busy)return;window.RayRatioLive?.accept();window.RaySession?.record();fn(p);BODY.hide=false;window.RayLayers?.invalidate();bodyUI();syncBody();queue();window.RaySession?.record(label);refresh();}
 for(const b of block.querySelectorAll('[data-region-mode]'))b.onclick=()=>{mode=b.dataset.regionMode;BODY.hide=false;syncBody();refresh();};
 for(const b of block.querySelectorAll('[data-region-action]'))b.onclick=()=>change(b.textContent,p=>{const name=b.dataset.regionAction,percent=clamp(Number(block.querySelector('input[type=number]').value)||2,.5,10)/100;if(name==='clear'){p.regionStrokes=[];return;}const action={slim:['width',-percent],expand:['width',percent],'frame-in':['frame',-.025],'frame-out':['frame',.025],left:['x',-Math.max(1,source.width*.002)],right:['x',Math.max(1,source.width*.002)],up:['y',-Math.max(1,source.height*.002)],down:['y',Math.max(1,source.height*.002)]}[name];if(action)Object.assign(p,core.step(p,...action,source.width,source.height));});
 brush.oninput=refresh;block.querySelector('input[type=checkbox]').onchange=e=>change('Bảo vệ cánh tay',p=>{p.regionProtectArms=e.target.checked;});
 function point(e,g){return[clamp((e.clientX-g.ox)/(g.W*g.k),0,1),clamp((e.clientY-g.oy)/(g.H*g.k),0,1)];}
 RayControls.bindDrag(overlay,{start(e){const g=bodyGeo(),p=part();if(!editing()||mode==='off'||!g||!p)return;window.RayRatioLive?.accept();window.RaySession?.record();const stroke={mode,size:Number(brush.value),softness:.7,points:[point(e,g)]};const previous=p.regionStrokes||[];p.regionStrokes=[...previous,stroke];paint();return{g,p,previous,stroke};},move(s,e){const last=s.stroke.points.at(-1),next=point(e,s.g);if(Math.hypot((next[0]-last[0])*source.width,(next[1]-last[1])*source.height)<1)return;s.stroke={...s.stroke,points:[...s.stroke.points.slice(-1023),next]};s.p.regionStrokes=[...s.previous,s.stroke];window.RayLayers?.invalidate();queue();paint();},end(){window.RayLayers?.invalidate();queue();window.RaySession?.record('Sửa vùng chỉnh dáng bằng bút');refresh();}});
 function paint(){if(overlay.hidden)return;const g=bodyGeo(),p=part();if(!g||!p)return;const r=wrap.getBoundingClientRect(),dpr=Math.min(2,devicePixelRatio||1);overlay.width=Math.round(r.width*dpr);overlay.height=Math.round(r.height*dpr);const c=overlay.getContext('2d');c.scale(dpr,dpr);for(const stroke of p.regionStrokes||[]){c.strokeStyle=stroke.mode==='erase'?'rgba(255,116,139,.55)':'rgba(112,231,218,.55)';c.fillStyle=c.strokeStyle;c.lineWidth=stroke.size*Math.min(source.width,source.height)*g.k;c.lineCap=c.lineJoin='round';c.beginPath();stroke.points.forEach(([x,y],i)=>{const px=g.ox-r.left+x*g.W*g.k,py=g.oy-r.top+y*g.H*g.k;if(i)c.lineTo(px,py);else c.moveTo(px,py);});if(stroke.points.length===1){const [x,y]=stroke.points[0];c.arc(g.ox-r.left+x*g.W*g.k,g.oy-r.top+y*g.H*g.k,c.lineWidth/2,0,Math.PI*2);c.fill();}else c.stroke();}}
 const ui=bodyUI;bodyUI=function(...args){const value=ui.apply(this,args);refresh();return value;};const sync=syncBody;syncBody=function(...args){const value=sync.apply(this,args);refresh();return value;};const reset=$('bodyReset1').onclick;$('bodyReset1').onclick=function(...args){const p=part();if(p){p.regionStrokes=[];p.regionProtectArms=true;}return reset.apply(this,args);};const clear=$('bodyResetAll').onclick;$('bodyResetAll').onclick=function(...args){for(const p of BODY.parts){p.regionStrokes=[];p.regionProtectArms=true;}return clear.apply(this,args);};new MutationObserver(refresh).observe(document.body,{attributes:true,attributeFilter:['data-editor-tool']});new ResizeObserver(paint).observe(wrap);refresh();
})();
